// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/0x627fa62ccbb1c1b04ffaecd72a53e37fc0e17839.sol";

contract MaliciousToken {
    mapping(address => uint256) public balances;

    constructor() payable {}

    function mint(address to, uint256 amount) external {
        balances[to] += amount;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balances[msg.sender] >= amount, "Insufficient balance");
        balances[msg.sender] -= amount;
        balances[to] += amount;
        return true;
    }
}

contract UnderflowTest is Test {
    TokenBank public tokenBank;
    MaliciousToken public token;
    address owner = address(0xABCD);
    address holder = address(0x1234);

    function setUp() public {
        vm.prank(owner);
        tokenBank = new TokenBank();

        token = new MaliciousToken();
        token.mint(address(tokenBank), 100); // TokenBank gets 100 tokens
        vm.deal(holder, 1 ether);

        vm.prank(holder);
        tokenBank.Deposit{value: 1 ether}();
    }

    function testTokenBankWithdrawalResetsHolderStateWithoutTransfer() public {
        // Token balances before transfer attempt
        uint256 tokenBankBalanceBefore = token.balances(address(tokenBank));
        uint256 holderBalanceBefore = token.balances(holder);
        // = 100 | 0

        // Attempt to withdraw 101 tokens (more than TokenBank holds)
        vm.prank(owner);
        tokenBank.WitdrawTokenToHolder(holder, address(token), 101);

        // Balances should remain unchanged after transfer failure
        uint256 tokenBankBalanceAfter = token.balances(address(tokenBank));
        uint256 holderBalanceAfter = token.balances(holder);
        assertEq(tokenBankBalanceAfter, tokenBankBalanceBefore, "TokenBank balance unchanged");
        assertEq(holderBalanceAfter, holderBalanceBefore, "Holder balance unchanged");

        // Verify holder status is reset despite transfer failure
        vm.prank(owner);
        tokenBank.WitdrawTokenToHolder(holder, address(token), 0);

        uint256 tokenBankBalanceFinal = token.balances(address(tokenBank));
        uint256 holderBalanceFinal = token.balances(holder);
        assertEq(tokenBankBalanceFinal, tokenBankBalanceBefore, "TokenBank balance persists");
        assertEq(holderBalanceFinal, holderBalanceBefore, "Holder still lacks tokens");

        // Manual token withdrawal verification
        vm.prank(owner);
        tokenBank.WithdrawToken(address(token), 100, address(this));
        uint256 tokenBankBalanceOwner = token.balances(address(tokenBank));
        uint256 testContractBalance = token.balances(address(this));
        assertEq(tokenBankBalanceOwner, 0, "TokenBank emptied by owner");
        assertEq(testContractBalance, 100, "Tokens withdrawn despite invalid holder state");
    }
}
```
